ALTER TABLE "organizations" DROP CONSTRAINT "organizations_payment_service_reason_check";--> statement-breakpoint
ALTER TABLE "organizations" ADD CONSTRAINT "organizations_payment_service_reason_check" CHECK (("organizations"."payment_service_status" = 'active' AND "organizations"."payment_service_reason" IS NULL AND "organizations"."payment_service_since" IS NULL) OR ("organizations"."payment_service_status" = 'suspended' AND "organizations"."payment_service_reason" IN ('token', 'tingee_disabled', 'credential_invalid', 'gateway_permission_missing', 'payout_account_not_allowed') AND "organizations"."payment_service_since" IS NOT NULL));